/* Configuration authoring mock; all edits live only in this document's memory. */
(() => {
  'use strict';
  const C=window.ConfigurationPrototype, root=document.querySelector('#configuration-root');
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const pages={workflows:['检查流程','配置用户能发起的检查，以及对应的方法和只读工具。'],systems:['系统设置','在系统下管理基本信息和所属环境。'],environments:['环境配置','为系统配置可用环境、默认模型与只读资源范围。'],models:['模型配置','管理对话中的模型名称，以及对应的执行连接与 Agent。'],permissions:['权限配置','按成员角色限定系统、环境、模型和资料访问。'],resources:['资源目录','自定义代码项目、MCP 与 Skill，再关联到具体环境。']};
  const selections={workflows:'report',systems:'orders',environments:'orders-test',models:'general',permissions:'tester',resources:'demo-orders-code'};
  const providers={control:'总控适配器',direct:'受控 ACP 直连'};
  let page='systems',notice='',trigger,resourceType='projects',resourceReturn=null,pendingFocus=null,issuesShown=false,workflowOpen=false;
  const btn=(id,text,cls='')=>`<button type="button" data-admin="${id}" class="${cls}">${text}</button>`;
  const text=(label,field,value,extra='')=>`<label class="admin-field">${label}<input data-field="${field}" value="${esc(value)}" ${extra}></label>`;
  const toggle=(label,field,value,help='')=>`<label class="admin-toggle"><span>${label}${help?`<small>${help}</small>`:''}</span><input type="checkbox" data-field="${field}" ${value?'checked':''}></label>`;
  const select=(label,field,value,items)=>`<label class="admin-field">${label}<select data-field="${field}">${items.map(([id,name])=>`<option value="${id}" ${id===value?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`;
  const group=()=>page==='permissions'?'roles':page==='resources'?resourceType:page;
  const selected=()=>C.draft()[group()].find(x=>x.id===selections[page]);
  function environmentList(x){const rows=C.draft().environments.filter(e=>e.system===x.id);return `<h3>所属环境</h3><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>环境</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.name)}</td><td>${e.enabled?'已启用':'已停用'}</td><td><button type="button" data-open-environment="${e.id}">配置</button></td></tr>`).join('')||'<tr><td colspan="3">暂无环境，添加后再授予用户访问权限。</td></tr>'}</tbody></table></div><button type="button" data-add-environment="${x.id}">＋ 添加环境</button>`;}
  function systems(x){return `<h2>用户看到的系统</h2><p class="admin-muted">固定流程：只读问题检查 · 示例。用户通过对话发起，不需要配置流程。</p>${text('系统名称','name',x.name,'maxlength="40"')}${text('负责团队','owner',x.owner)}${text('用途说明 / 业务背景','description',x.description,'maxlength="2000"')}${environmentList(x)}${toggle('在用户端提供此系统','enabled',x.enabled,'停用后不再接受新的检查，既有记录保留。')}<h3>常用检查问题</h3><p class="admin-muted">显示在用户输入框上方，点击后填入问题。</p>${['核对报表与明细差异','排查接口异常','分析错误日志'].map(p=>`<label class="admin-check"><input type="checkbox" data-prompt="${p}" ${x.prompts.includes(p)?'checked':''}>${p}</label>`).join('')}`;}
  function environments(x){const d=C.draft(),sys=d.systems.find(s=>s.id===x.system);return `<h2>${esc(sys.name)} / 环境设置</h2>${select('所属系统','system',x.system,d.systems.map(s=>[s.id,s.name]))}${text('环境名称','name',x.name,'maxlength="40"')}<label class="admin-field">环境说明 / 数据口径<textarea data-field="description" rows="3" maxlength="2000">${esc(x.description||'')}</textarea></label><div class="admin-two">${text('数据时区','timezone',x.timezone||'Asia/Shanghai')}${text('预期数据延迟（分钟）','dataDelayMinutes',x.dataDelayMinutes??0,'type="number" min="0" max="10080"')}</div>${text('部署版本标记（可空，待核实）','deploymentRef',x.deploymentRef||'')}<p class="admin-muted">背景说明进入本轮上下文；结构化资源绑定负责实际准入。配置值不等于实时观测。</p>${select('默认模型','defaultModel',x.defaultModel,d.models.map(m=>[m.id,m.name+(m.enabled?'':' · 已停用')]))}${toggle('在用户端提供此环境','enabled',x.enabled)}${toggle('允许对话理解（不授权业务工具）','understandingAllowed',x.understandingAllowed!==false,'只允许发送获权消息；附件内容另行授权。关闭后仅保存材料。')}${toggle('本环境要求硬 Token / 内部调用限额','requireHardModelLimits',!!x.requireHardModelLimits,'能力未验证则阻断此要求的流程，不静默降级。')}${window.ResourceDesign.environment(x,d)}<div class="admin-note">代码地址、MCP 和 Skill 都来自可扩展目录。计划准备时固定资源修订；配置变化不迁移在途执行。</div>`;}
  function resources(x){return `<div class="resource-tabs">${[['projects','代码项目'],['mcps','MCP 服务'],['skills','Skill 方法']].map(([id,name])=>`<button type="button" data-resource-tab="${id}" aria-pressed="${resourceType===id}">${name}</button>`).join('')}</div>`+window.ResourceDesign.editor(resourceType,x,C.draft());}

  function models(x){const d=C.draft(),a=d.agentConnections.find(a=>a.id===x.connectionId);return `<a href="#admin-integrations">← Agent 与模型接入</a><h2>模型预设</h2>${text('用户显示名称','name',x.name,'maxlength="40"')}${select('Agent 执行连接','connectionId',x.connectionId||'',d.agentConnections.map(a=>[a.id,a.name+(a.enabled?'':' · 已停用')]))}${select('该 Agent 发现的模型（合成）','quotaModelId',x.quotaModelId||'',(a?.catalog||[]).map(id=>[id,id]))}<p class="admin-muted">先在连接中完成发现，再发布此预设。当前清单为合成数据，实际模型和认证未知；预设不自动授予任何环境或用户。</p>${toggle('发布此模型预设（离线）','enabled',x.enabled)}<p>下一步：<a href="#admin-systems">系统环境绑定</a>，再到<a href="#admin-permissions">用户角色授权</a>。</p>`;}
  function permissions(x){const d=C.draft();return `${window.ContextQuota.globalEditor(d)}<h2>${esc(x.name)}的使用范围</h2><h3>系统与环境</h3><div class="admin-check-grid">${d.environments.map(env=>`<label class="admin-check"><input type="checkbox" data-grant="environments" value="${env.id}" ${x.environments.includes(env.id)?'checked':''}>${esc(d.systems.find(s=>s.id===env.system).name)} / ${esc(env.name)}</label>`).join('')}</div><h3>可用检查流程</h3>${d.workflows.map(w=>`<label class="admin-check"><input type="checkbox" data-grant="workflowIds" value="${w.id}" ${(x.workflowIds||[]).includes(w.id)?'checked':''}>${esc(w.name)}</label>`).join('')}<h3>可选模型</h3>${d.models.map(m=>`<label class="admin-check"><input type="checkbox" data-grant="models" value="${m.id}" ${x.models.includes(m.id)?'checked':''}>${esc(m.name)}</label>`).join('')}<h3>资料访问</h3>${toggle('添加附件','attachments',x.attachments,'原型只展示文件名；正式上传和内容读取分别鉴权。')}${toggle('下载检查文件','download',x.download,'对每份产物重新鉴权；本页仅配置和预览。')}${toggle('查看本人历史对话','history',x.history,'不包含他人的会话。原型未接入真实身份。')}${toggle('查看执行事件','events',x.events,'事件与诊断不是公开数据；本页仅配置和预览。')}<h3>执行方式、审批与用量</h3>${select('角色默认执行方式','executionMode',x.executionMode||'confirm',window.ResourceDesign.modes)}${toggle('允许用户获配自动只读检查','allowAutoRead',x.allowAutoRead,'仍受环境、资源和预算约束；不是任意自动执行。')}${toggle('允许确认本人会话的只读计划','canApproveRead',x.canApproveRead,'不包含写入或替他人批准；未授权时交由责任人。')}${text('审批责任人','approver',x.approver)}<div class="admin-two">${text('角色内部调用目标上限','maxCalls',x.maxCalls,'type="number" min="1" max="100"')}${text('角色并发上限','concurrency',x.concurrency,'type="number" min="1" max="5"')}</div><p class="admin-muted">固定只读策略；具体操作执行前确认。受控写入不在本轮范围。数量与费用需后端落实，这里不声称已硬性限制。</p>`;}
  function workflows(x){const d=C.draft();return `<section class="ops-panel workflow-table"><div class="ops-panel-head"><h2>检查流程</h2><span class="ops-source-label">固定模板 · 应用后供新计划使用</span></div><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>流程名称</th><th>适用检查</th><th>状态</th><th>依赖</th><th>操作</th></tr></thead><tbody>${d.workflows.map(w=>`<tr><td class="ops-subject"><strong>${esc(w.name)}</strong><small>配置修订 ${w.revision}</small></td><td class="workflow-description">${esc(w.purpose)}</td><td><span class="ops-status ${w.enabled?'success':'muted'}">${w.enabled?'已启用':'已停用'}</span></td><td>${w.skillIds.length} 项 Skill · ${String(w.tools).split(',').filter(v=>v.trim()).length} 项只读工具</td><td>${`<button type="button" data-record="${w.id}" class="ops-link">配置</button>`}</td></tr>`).join('')}</tbody></table></div></section>${workflowOpen?`<section class="admin-editor"><div class="admin-form"><h2>${esc(x.name)} · 流程配置</h2>${text('流程名称','name',x.name)}${text('检查目标','purpose',x.purpose)}<div class="workflow-chain"><span>补齐条件</span><i>→</i><span>授权 / 审批</span><i>→</i><span>只读取证</span><i>→</i><span>交付待验证</span></div><h3>所需只读工具</h3>${d.mcps.flatMap(m=>String(m.tools).split(',').map(t=>t.trim()).filter(Boolean).map(t=>`<label class="admin-check"><input type="checkbox" data-flow-tool="${esc(m.id+'::'+t)}" ${String(x.tools).split(',').map(v=>v.trim()).includes(m.id+'::'+t)?'checked':''}>${esc(m.name)} / ${esc(t)}</label>`)).join('')}<h3>检查方法</h3>${d.skills.map(skill=>`<label class="admin-check"><input type="checkbox" data-grant="skillIds" value="${skill.id}" ${(x.skillIds||[]).includes(skill.id)?'checked':''}>${esc(skill.name)}</label>`).join('')}${toggle('需要读取代码','readCode',x.readCode)}${toggle('开放此检查流程','enabled',x.enabled)}<p class="admin-muted">模型取用户获准的预设；工具和 Skill 必须同时被目标环境允许。流程不增加资源权限。</p></div></section>`:'<section class="workflow-overview"><p>选择“配置”查看该流程。用户仍通过对话提问，不需要自己编排步骤。</p></section>'}`;}
  function preview(){const v=C.visible(C.draft()),rows=[['系统',v.systems.map(x=>x.name).join('、')||'无可用系统'],['环境',v.environments.map(x=>x.name).filter((x,i,a)=>a.indexOf(x)===i).join('、')||'无可用环境'],['模型',v.models.map(x=>x.name).join('、')||'无可用模型'],['附件',v.role.attachments?'允许添加':'不可添加'],['文件下载',v.role.download?'允许（仍需逐项授权）':'不允许'],['历史 / 事件',`${v.role.history?'本人历史':'不提供历史'} / ${v.role.events?'允许事件':'不提供事件'}`]];return `<h2>用户端预览</h2><label class="admin-field">预览身份<select id="admin-preview-role">${C.draft().roles.map(r=>`<option value="${r.id}" ${C.role()===r.id?'selected':''}>${r.name}</option>`).join('')}</select></label><p class="admin-muted">下方展示草稿效果。对话读取已应用配置；身份切换仅用于离线评审。</p><dl>${rows.map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl><a class="admin-preview-link" href="#chat">返回用户对话 ↗</a><div class="admin-note">用户只选择已配置、已获权限的选项，无需理解后端或权限规则。</div>`;}
  function render(next=page,focus=false){
    if(window.ServiceDesignPrototype?.has(next)){window.ServiceDesignPrototype.render(next,focus);return;}
    root.dataset.mode='configuration';page=pages[next]?next:'systems';const d=C.draft();if(!selected())selections[page]=d[group()][0].id;const x=selected(),items=page==='environments'?d.environments.filter(e=>e.system===x.system):d[group()];
    root.innerHTML=window.ServiceDesignPrototype.managementHeader()+window.ServiceDesignPrototype.navigation(page)+`<main class="admin-main"><header class="admin-heading"><div><div class="admin-eyebrow">${page==='environments'?`<button type="button" data-parent-system="${x.system}">系统设置</button> / ${esc(d.systems.find(sys=>sys.id===x.system)?.name)} / 环境`:'平台管理 / 对话配置'}</div><h1 tabindex="-1">${pages[page][0]}</h1><p>${pages[page][1]}</p></div><span class="admin-badge">合成配置管理员</span></header><div class="admin-toolbar"><span id="admin-draft-status"></span><div>${btn('discard','放弃当前草稿')}${btn('publish-set','选择变更集')}${btn('publish','预览并应用当前对象','admin-primary')}</div></div><div id="admin-feedback" role="status" aria-live="polite">${esc(notice)}</div><div id="admin-validation"></div>${page==='workflows'?workflows(x):`<div class="admin-columns"><section class="admin-editor">${page==='environments'?`<label class="admin-field system-scope-picker">当前系统<select id="environment-system-filter">${d.systems.map(sys=>`<option value="${sys.id}" ${sys.id===x.system?'selected':''}>${esc(sys.name)}</option>`).join('')}</select></label>`:''}<div class="admin-records" aria-label="配置记录">${page!=='permissions'?btn('add','＋ 新增'): ''}${items.map(i=>`<button data-record="${i.id}" ${i.id===x.id?'aria-pressed="true"':''}>${esc(page==='environments'?d.systems.find(s=>s.id===i.system).name+' / '+i.name:i.name)}${i.enabled===false?'<span>已停用</span>':''}</button>`).join('')}</div><div class="admin-form">${page==='resources'&&resourceReturn?`<button type="button" data-admin="return-environment" class="config-return">← 返回 ${esc(resourceReturn.name)} 环境配置</button>`:''}${({systems,environments,models,permissions,resources})[page](x)}</div></section><aside class="admin-preview">${preview()}</aside></div>`}<details class="admin-audit"><summary>本次演示的配置记录（${C.audit().length}）</summary>${C.audit().length?C.audit().map(a=>`<p>配置修订 ${a.revision} · ${esc(a.actor)} · ${esc(a.at)}<br>${esc(a.changes.join('；'))}</p>`).join(''):'<p>暂无应用记录。草稿尚未影响用户对话。</p>'}</details></main><dialog id="admin-dialog" aria-labelledby="admin-dialog-title"></dialog>`;
    updatePreview();if(focus)root.querySelector('h1').focus();if(pendingFocus){const issue=pendingFocus;pendingFocus=null;focusField(issue);}
    root.querySelector('#admin-dialog').addEventListener('cancel',()=>setTimeout(()=>trigger?.focus(),0));
  }
  function focusField(issue){if(issue.type==='quotaDefaults'){const detail=root.querySelector('.admin-details');if(detail)detail.open=true;root.querySelector('[data-quota-default]')?.focus();return;}const el=root.querySelector(`[data-field="${issue.field}"],[data-grant="${issue.field}"]`);if(el){el.setAttribute('aria-invalid','true');el.setAttribute('aria-describedby','admin-validation');el.focus();el.scrollIntoView({block:'center'});}}
  function renderIssues(){const target=root.querySelector('#admin-validation');if(!issuesShown){target.innerHTML='';return;}const issues=C.issues(),d=C.draft();target.innerHTML=issues.length?`<section class="config-validation" aria-label="需要修正的配置"><strong>${issues.length} 处需要修正</strong><ul>${issues.map((x,i)=>`<li><span>${esc(d[x.type].find(y=>y.id===x.id)?.name||x.id)}：${esc(x.message)}</span><button type="button" data-admin="locate" data-issue="${i}">前往修正 →</button></li>`).join('')}</ul></section>`:'';for(const el of root.querySelectorAll('[aria-invalid]')){el.removeAttribute('aria-invalid');el.removeAttribute('aria-describedby');}for(const x of issues)if(x.id===selections[page]){const el=root.querySelector(`[data-field="${x.field}"],[data-grant="${x.field}"]`);if(el)el.setAttribute('aria-invalid','true');}}
  function updatePreview(){const count=C.changes().length;root.querySelector('#admin-draft-status').textContent=`已应用配置修订 ${C.current().revision} · ${count?'有 '+count+' 项未应用改动':'全部改动已应用'}`;if(root.querySelector('.admin-preview'))root.querySelector('.admin-preview').innerHTML=preview();for(const action of ['publish','discard'])root.querySelector(`[data-admin=${action}]`).disabled=!count;renderIssues();}
  function go(target,issue=null){pendingFocus=issue;if(location.hash==='#admin-'+target)render(target);else location.hash='admin-'+target;}
  root.addEventListener('input',e=>{if(root.dataset.mode==='service')return;if(e.target.dataset.quotaDefault){C.draft().quotaDefaults[0][e.target.dataset.quotaDefault]=e.target.value===''?null:Number(e.target.value);updatePreview();return;}if(e.target.dataset.projectRef){const x=selected();x.projectRefs??={};x.projectRefs[e.target.dataset.projectRef]=e.target.value;updatePreview();return;}if(!e.target.dataset.field||e.target.type==='checkbox'||e.target.tagName==='SELECT')return;const value=e.target.type==='number'?Number(e.target.value):e.target.value;selected()[e.target.dataset.field]=value;updatePreview();});
  root.addEventListener('change',e=>{if(e.target.id==='quota-hard-required'){C.draft().quotaDefaults[0].hardModelLimits=e.target.checked;updatePreview();return;}if(root.dataset.mode==='service'||e.target.dataset.projectRef||e.target.dataset.quotaDefault||e.target.id==='code-access-token')return;
    if(e.target.id==='environment-system-filter'){const env=C.draft().environments.find(x=>x.system===e.target.value);if(env){selections.environments=env.id;render();}else{selections.systems=e.target.value;go('systems');}return;}
    if(e.target.dataset.flowTool){const values=String(selected().tools).split(',').map(v=>v.trim()).filter(Boolean),ref=e.target.dataset.flowTool;selected().tools=(e.target.checked?[...new Set([...values,ref])]:values.filter(x=>x!==ref)).join(', ');updatePreview();return;}
    if(e.target.dataset.field&&e.target.type!=='checkbox'&&e.target.tagName!=='SELECT')return;
    const x=selected();
    if(e.target.dataset.field){x[e.target.dataset.field]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(e.target.dataset.field==='connectionId'){const a=C.draft().agentConnections.find(a=>a.id===x.connectionId);x.provider=a.provider;x.agentId=a.agentId;x.agent=a.name;x.quotaModelId=a.catalog.includes(x.quotaModelId)?x.quotaModelId:a.catalog[0]||'';}if(e.target.dataset.field==='provider'){x.agent=x.provider==='control'?'示例 Agent A':'示例 Agent B';x.connectionId='demo-'+x.provider;x.agentId='demo-agent-'+x.provider;}}
    if(e.target.dataset.prompt)x.prompts=e.target.checked?[...new Set([...x.prompts,e.target.dataset.prompt])]:x.prompts.filter(p=>p!==e.target.dataset.prompt);
    if(e.target.dataset.grant){const key=e.target.dataset.grant;x[key]=e.target.checked?[...new Set([...x[key],e.target.value])]:x[key].filter(v=>v!==e.target.value);}
    if(e.target.id==='admin-preview-role')C.setRole(e.target.value);
    const focusSelector=e.target.dataset.field?'[data-field="'+e.target.dataset.field+'"]':e.target.dataset.grant?'[data-grant="'+e.target.dataset.grant+'"][value="'+e.target.value+'"]':e.target.dataset.prompt?'[data-prompt="'+e.target.dataset.prompt+'"]':e.target.id?'#'+e.target.id:null;const top=scrollY;render();if(focusSelector)root.querySelector(focusSelector)?.focus({preventScroll:true});window.scrollTo(0,top);
  });
  root.addEventListener('click',e=>{if(root.dataset.mode==='service')return;
    const b=e.target.closest('button');if(!b)return;
    if(b.dataset.admin==='review-mcp'&&page==='resources'&&resourceType==='mcps'){const x=selected();x.reviewFingerprint=window.ResourceDesign.mcpFingerprint(x);notice='仅确认填写的合成工具范围；未发现真实工具、未连接 MCP。';render();return;}
    if(b.dataset.parentSystem){selections.systems=b.dataset.parentSystem;go('systems');return;}
    if(b.dataset.openEnvironment){selections.environments=b.dataset.openEnvironment;go('environments');return;}
    if(b.dataset.addEnvironment){const d=C.draft(),id='demo-environments-'+(d.environments.length+1);d.environments.push({id,system:b.dataset.addEnvironment,name:'新环境 '+(d.environments.length+1),description:'',timezone:'Asia/Shanghai',dataDelayMinutes:0,deploymentRef:'',enabled:false,defaultModel:d.models[0].id,allowedModelIds:[d.models[0].id],contextPolicyId:d.contextPolicies[0].id});selections.environments=id;go('environments');return;}
    if(b.dataset.codeToken&&page==='resources'&&resourceType==='projects'){const x=selected(),field=root.querySelector('#code-access-token');if(b.dataset.codeToken==='save'){if(!field?.value.trim()){notice='请先填写虚构的演示 Token。';root.querySelector('#admin-feedback').textContent=notice;return;}field.value='';x.credentialVersion=(x.credentialVersion||0)+1;x.credentialRef='secret-ref/demo-code-'+x.id+'-v'+x.credentialVersion;notice='仅生成了演示凭据引用，输入值已清空，未保存或验证 Token。请预览并应用配置。';}else{x.credentialRef='';if(field)field.value='';notice='已清除草稿中的凭据引用；尚未应用。';}render();return;}
    if(b.dataset.openResource){resourceReturn={id:selected().id,name:selected().name};resourceType=b.dataset.openResource;selections.resources=C.draft()[resourceType][0]?.id;go('resources');return;}
    if(b.dataset.admin==='return-environment'&&resourceReturn){selections.environments=resourceReturn.id;resourceReturn=null;go('environments');return;}
    if(b.dataset.admin==='locate'){const issue=C.issues()[Number(b.dataset.issue)];if(!issue)return;const governancePage={agentConnections:'integrations',runtimeProfiles:'runtime',contextPolicies:'context'}[issue.type];if(governancePage){go(governancePage);return;}const target=['projects','mcps','skills'].includes(issue.type)?'resources':['roles','quotaDefaults'].includes(issue.type)?'permissions':issue.type;if(target==='resources')resourceType=issue.type;if(issue.type!=='quotaDefaults')selections[target]=issue.id;go(target,issue);return;}
    if(b.dataset.resourceTab){resourceType=b.dataset.resourceTab;selections.resources=C.draft()[resourceType][0]?.id;render();return;}
    if(b.dataset.admin==='add'){const d=C.draft(),id='demo-'+group()+'-'+(d[group()].length+1);let item;if(page==='systems')item={id,name:'新系统 '+(d.systems.length+1),owner:'待指定团队',description:'',enabled:false,prompts:[]};if(page==='environments')item={id,system:selected()?.system||selections.systems,name:'新环境 '+(d.environments.length+1),enabled:false,defaultModel:d.models[0].id,allowedModelIds:[d.models[0].id],contextPolicyId:d.contextPolicies[0].id};if(page==='models')item={id,name:'新模型预设 '+(d.models.length+1),provider:'control',agent:'示例 Agent A',connectionId:'demo-control',agentId:'demo-agent-control',quotaModelId:'demo-model-general',enabled:false};if(page==='resources')item=window.ResourceDesign.blank(resourceType,d[resourceType].length+1);if(item){d[group()].push(item);selections[page]=id;render();}return;}
    if(b.dataset.record){selections[page]=b.dataset.record;if(page==='workflows')workflowOpen=true;render();if(page==='workflows')root.querySelector('.admin-form')?.scrollIntoView({block:'start'});return;}
    const dialog=root.querySelector('#admin-dialog');
    if(['publish','publish-set','publish-quota'].includes(b.dataset.admin)){
      const token=root.querySelector('#code-access-token');if(token?.value){token.value='';notice='未模拟保存的 Token 已清空，请先完成凭据配置再应用。';root.querySelector('#admin-feedback').textContent=notice;return;}
      const selectedKeys=b.dataset.admin==='publish-quota'?['quotaDefaults:global']:[group()+':'+selected().id];const result=b.dataset.admin==='publish-set'?{errors:[],ok:true}:C.preview(selectedKeys);const errors=result.errors;if(errors.length||!C.changes().length){notice=errors.join(' ')||'没有待应用的改动。';issuesShown=!!errors.length;root.querySelector('#admin-feedback').textContent=notice;renderIssues();const local=C.issues().find(x=>x.id===selections[page]);if(local)focusField(local);return;}
      trigger=b;dialog.innerHTML=`<h2 id="admin-dialog-title">应用这份演示配置？</h2>${C.selectionFields(selectedKeys)}<p>新对话读取新配置。未选草稿保留；仅实际依赖的语义变化使待审批计划失效。在途快照不改写，停用和撤权仍阻断。不会调用真实资源。</p><div class="admin-dialog-actions">${btn('cancel','继续编辑')}${btn('confirm','应用到离线演示','admin-primary')}</div>`;dialog.showModal();
    }
    if(b.dataset.admin==='discard'){trigger=b;dialog.innerHTML=`<h2 id="admin-dialog-title">放弃当前对象的未应用改动？</h2><p>仅当前对象恢复到已应用内容；其他页面的草稿保留。</p><div class="admin-dialog-actions">${btn('cancel','继续编辑')}${btn('confirm-discard','放弃草稿')}</div>`;dialog.showModal();}
    if(b.dataset.admin==='cancel'){dialog.close();trigger?.focus();}
    if(b.dataset.admin==='confirm'){const result=C.publish(C.readSelection(dialog));if(!result.ok){dialog.querySelector('[data-publish-error]').textContent=result.errors.join('；');return;}notice=result.ok?'已应用到离线演示。可返回用户对话查看可选项。':result.errors.join(' ');dialog.close();render(page,true);}
    if(b.dataset.admin==='confirm-discard'){C.discard([group()+':'+selected().id]);issuesShown=false;notice='已放弃草稿，已应用配置未改变。';dialog.close();render(page,true);}
  });
  window.AdminPrototype={render,createForConnection(id){const d=C.draft(),a=d.agentConnections.find(a=>a.id===id);if(!a?.catalog.length)return;const mid='demo-models-'+(d.models.length+1);d.models.push({id:mid,name:'新模型预设 '+(d.models.length+1),connectionId:a.id,agentId:a.agentId,agent:a.name,provider:a.provider,quotaModelId:a.catalog[0],enabled:false});selections.models=mid;go('models');}};
})();
